(() => {
  'use strict';
  const engine = globalThis.AlarmPuzzleEngine;
  const PULL_DISTANCE = 82;

  function attach(document, view) {
    const get = (id) => document.getElementById(id);
    const pump = get('pump');
    const status = get('status');
    const restart = get('restart');
    const balloons = Array.from({ length: engine.BALLOONS }, (_, i) => get(`balloon-${i}`));
    let state = engine.createState();
    let drag = null;

    function render() {
      pump.style.setProperty('--pull', `${state.pull * PULL_DISTANCE}px`);
      pump.classList.toggle('dragging', drag !== null);
      pump.disabled = state.phase === 'done';
      pump.setAttribute('aria-label', `공기 흡입 펌프 손잡이, ${state.cleared}개 수거`);
      get('meter-fill').style.width = `${state.pull * 100}%`;
      get('counter').textContent = `수거 ${state.cleared} / 3`;
      get('basket-count').textContent = Array.from({ length: 3 }, (_, i) => i < state.cleared ? '●' : '○').join(' ');
      get('finish').hidden = state.phase !== 'done';
      get('pull-hint').hidden = state.phase === 'done';
      balloons.forEach((balloon, i) => {
        balloon.classList.toggle('collected', i < state.cleared);
        balloon.classList.toggle('active', i === state.cleared);
        balloon.style.setProperty('--scale', String(0.57 + 0.43 * engine.pressure(state, i)));
        balloon.setAttribute('aria-hidden', String(i < state.cleared));
      });
    }

    function finishPull() {
      const previous = state;
      state = engine.release(state);
      if (state.phase === 'done') {
        status.textContent = '모든 알림 수거 완료. 다시 시작할 수 있어요.';
      } else if (state.cleared > previous.cleared) {
        status.textContent = `풍선 하나 수거! ${3 - state.cleared}개 남았어요.`;
      } else if (state.strokes > previous.strokes) {
        status.textContent = '바람이 빠졌어요. 한 번 더 당기면 수거돼요.';
      } else {
        status.textContent = '조금 더 아래로 당겨요. 끝에 닿으면 놓아주세요.';
      }
      render();
      if (state.phase === 'done') restart.focus();
    }

    function stopDrag(cancelled) {
      if (!drag) return;
      const pointerId = drag.id;
      drag = null;
      if (pump.hasPointerCapture(pointerId)) pump.releasePointerCapture(pointerId);
      if (cancelled) {
        state = engine.cancel(state);
        status.textContent = '당기기를 멈췄어요. 다시 손잡이를 잡아주세요.';
        render();
      } else finishPull();
    }

    pump.addEventListener('pointerdown', (event) => {
      if (state.phase === 'done' || drag || event.button !== 0) return;
      event.preventDefault();
      drag = { id: event.pointerId, startY: event.clientY };
      pump.setPointerCapture(event.pointerId);
      status.textContent = '손잡이를 아래로 당겨 공기를 빼요.';
      render();
    });
    pump.addEventListener('pointermove', (event) => {
      if (!drag || event.pointerId !== drag.id) return;
      state = engine.pull(state, (event.clientY - drag.startY) / PULL_DISTANCE);
      status.textContent = state.pull >= engine.THRESHOLD ? '좋아요, 이제 놓아주세요!' : '당기는 만큼 풍선이 작아져요. 아래로 더!';
      render();
    });
    pump.addEventListener('pointerup', (event) => {
      if (drag && event.pointerId === drag.id) stopDrag(false);
    });
    for (const name of ['pointercancel', 'lostpointercapture']) {
      pump.addEventListener(name, (event) => {
        if (drag && event.pointerId === drag.id) stopDrag(true);
      });
    }
    view.addEventListener('blur', () => stopDrag(true));
    pump.addEventListener('keydown', (event) => {
      if (!['ArrowDown', ' ', 'Enter'].includes(event.key)) return;
      event.preventDefault();
      if (event.repeat || drag || state.phase === 'done') return;
      state = engine.pull(state, 1);
      finishPull();
    });
    restart.addEventListener('click', () => {
      stopDrag(true);
      state = engine.createState();
      status.textContent = '풍선 하나에 두 번. 손잡이를 아래로 당겨요.';
      render();
      pump.focus();
    });
    render();
    return { getState: () => ({ ...state }) };
  }

  globalThis.AlarmPuzzleApp = Object.freeze({ attach });
  if (typeof document !== 'undefined') attach(document, globalThis);
})();

