import test from 'node:test';
import assert from 'node:assert/strict';
import { readFileSync } from 'node:fs';
import vm from 'node:vm';

const source = (path) => readFileSync(new URL(`../${path}`, import.meta.url), 'utf8');
const context = vm.createContext({});
vm.runInContext(source('src/puzzle.js'), context);
vm.runInContext(source('src/app.js'), context);
const engine = context.AlarmPuzzleEngine;
const plain = (value) => JSON.parse(JSON.stringify(value));
const stroke = (state) => engine.release(engine.pull(state, 1));

test('new puzzle begins with three full balloons and zero collected', () => {
  const state = engine.createState();
  assert.deepEqual(plain(state), { strokes: 0, cleared: 0, pull: 0, phase: 'playing' });
  assert.deepEqual([0, 1, 2].map((i) => engine.pressure(state, i)), [1, 1, 1]);
});

test('partial pulling previews deflation without counting a stroke', () => {
  const initial = engine.createState();
  const preview = engine.pull(initial, 0.5);
  assert.equal(engine.pressure(preview, 0), 0.75);
  assert.equal(engine.pressure(preview, 1), 1);
  assert.equal(preview.strokes, 0);
  assert.equal(initial.pull, 0);
});

test('tap, upward pull and short pull cannot clear advertisements', () => {
  for (const distance of [0, -1, 0.3, engine.THRESHOLD - 0.01]) {
    assert.deepEqual(plain(engine.release(engine.pull(engine.createState(), distance))), plain(engine.createState()));
  }
});

test('threshold completes one stroke; second stroke collects the first balloon', () => {
  const first = engine.release(engine.pull(engine.createState(), engine.THRESHOLD));
  assert.equal(first.strokes, 1);
  assert.equal(first.cleared, 0);
  assert.equal(engine.pressure(first, 0), 0.5);
  const second = stroke(first);
  assert.equal(second.cleared, 1);
  assert.equal(engine.pressure(second, 0), 0);
  assert.equal(engine.pressure(second, 1), 1);
});

test('cancel discards even a full preview, preserving already completed work', () => {
  const state = stroke(engine.createState());
  assert.deepEqual(plain(engine.cancel(engine.pull(state, 1))), plain(state));
});

test('six full strokes finish and additional input cannot advance the score', () => {
  let state = engine.createState();
  for (let i = 0; i < 6; i++) state = stroke(state);
  assert.equal(state.phase, 'done');
  assert.equal(state.cleared, 3);
  assert.equal(state.strokes, 6);
  assert.deepEqual(plain(stroke(state)), plain(state));
});

test('invalid distances never corrupt progress; long pull is bounded', () => {
  for (const distance of [NaN, Infinity, undefined]) assert.equal(engine.pull(engine.createState(), distance).pull, 0);
  assert.equal(engine.pull(engine.createState(), 50).pull, 1);
});

class Element {
  constructor() {
    this.handlers = {};
    this.style = { setProperty(name, value) { this[name] = value; } };
    this.classes = new Set();
    this.classList = { toggle: (name, value) => value ? this.classes.add(name) : this.classes.delete(name) };
    this.attributes = {};
    this.captures = new Set();
    this.hidden = false;
    this.disabled = false;
    this.textContent = '';
    this.focused = false;
  }
  addEventListener(name, handler) { (this.handlers[name] ??= []).push(handler); }
  setAttribute(name, value) { this.attributes[name] = value; }
  setPointerCapture(id) { this.captures.add(id); }
  hasPointerCapture(id) { return this.captures.has(id); }
  releasePointerCapture(id) { this.captures.delete(id); this.emit('lostpointercapture', { pointerId: id }); }
  focus() { this.focused = true; }
  emit(name, fields = {}) {
    const event = { pointerId: 1, clientY: 100, button: 0, repeat: false, preventDefault() {}, ...fields };
    for (const handler of this.handlers[name] ?? []) handler(event);
  }
}

function fixture() {
  const elements = Object.fromEntries(['pump', 'status', 'restart', 'meter-fill', 'counter', 'basket-count', 'finish', 'pull-hint', 'balloon-0', 'balloon-1', 'balloon-2'].map((id) => [id, new Element()]));
  const view = new Element();
  const app = context.AlarmPuzzleApp.attach({ getElementById: (id) => elements[id] }, view);
  const pull = (endY = 182, pointerId = 1) => {
    elements.pump.emit('pointerdown', { pointerId });
    elements.pump.emit('pointermove', { clientY: endY, pointerId });
    elements.pump.emit('pointerup', { clientY: endY, pointerId });
  };
  return { elements, view, app, pull };
}

test('controller shows initial counter and hides the finish panel', () => {
  const { elements } = fixture();
  assert.equal(elements.counter.textContent, '수거 0 / 3');
  assert.equal(elements.finish.hidden, true);
  assert.equal(elements.pump.disabled, false);
});

test('pointer drag visibly previews handle, meter and balloon; release counts once', () => {
  const { elements, app } = fixture();
  elements.pump.emit('pointerdown');
  elements.pump.emit('pointermove', { clientY: 182 });
  assert.equal(elements.pump.style['--pull'], '82px');
  assert.equal(elements['meter-fill'].style.width, '100%');
  assert.ok(Number(elements['balloon-0'].style['--scale']) < 1);
  assert.match(elements.status.textContent, /놓아주세요/);
  elements.pump.emit('pointerup', { clientY: 182 });
  assert.equal(app.getState().strokes, 1);
  assert.equal(elements.pump.style['--pull'], '0px');
  elements.pump.emit('pointerup');
  assert.equal(app.getState().strokes, 1);
});

test('other pointer and right-button input do not take over the active hand', () => {
  const { elements, app } = fixture();
  elements.pump.emit('pointerdown', { button: 2 });
  elements.pump.emit('pointermove', { clientY: 182 });
  elements.pump.emit('pointerup');
  assert.equal(app.getState().strokes, 0);
  elements.pump.emit('pointerdown');
  elements.pump.emit('pointerdown', { pointerId: 2 });
  elements.pump.emit('pointermove', { pointerId: 2, clientY: 300 });
  elements.pump.emit('pointerup', { pointerId: 2 });
  assert.equal(app.getState().pull, 0);
  elements.pump.emit('pointermove', { clientY: 182 });
  elements.pump.emit('pointerup');
  assert.equal(app.getState().strokes, 1);
});

test('short drag and ordinary click cannot collect a balloon', () => {
  const { elements, app, pull } = fixture();
  pull(130);
  elements.pump.emit('click');
  assert.equal(app.getState().strokes, 0);
});

for (const reason of ['pointercancel', 'lostpointercapture', 'blur']) {
  test(`${reason} cancels a full pull without counting it`, () => {
    const { elements, view, app } = fixture();
    elements.pump.emit('pointerdown');
    elements.pump.emit('pointermove', { clientY: 200 });
    (reason === 'blur' ? view : elements.pump).emit(reason);
    elements.pump.emit('pointerup');
    assert.equal(app.getState().strokes, 0);
    assert.equal(app.getState().pull, 0);
  });
}

test('all six drags reveal completion and restart restores the initial puzzle', () => {
  const { elements, app, pull } = fixture();
  for (let i = 0; i < 6; i++) pull();
  assert.equal(elements.finish.hidden, false);
  assert.equal(elements.pump.disabled, true);
  assert.equal(elements.restart.focused, true);
  assert.equal(elements.counter.textContent, '수거 3 / 3');
  for (let i = 0; i < 3; i++) assert.equal(elements[`balloon-${i}`].attributes['aria-hidden'], 'true');
  elements.restart.emit('click');
  assert.deepEqual(plain(app.getState()), plain(engine.createState()));
  assert.equal(elements.finish.hidden, true);
  assert.equal(elements.pump.disabled, false);
  assert.equal(elements.pump.focused, true);
  assert.equal(elements['balloon-0'].classes.has('collected'), false);
});

test('keyboard alternative makes one stroke per deliberate press; repeat is ignored', () => {
  const { elements, app } = fixture();
  elements.pump.emit('keydown', { key: 'ArrowDown' });
  elements.pump.emit('keydown', { key: 'ArrowDown', repeat: true });
  assert.equal(app.getState().strokes, 1);
  elements.pump.emit('keydown', { key: ' ' });
  assert.equal(app.getState().cleared, 1);
});

test('entry point loads only local classic scripts and has every required DOM anchor', () => {
  const html = source('index.html');
  assert.ok(html.indexOf('src/puzzle.js') < html.indexOf('src/app.js'));
  assert.doesNotMatch(html, /https?:|type="module"/);
  for (const id of Object.keys(fixture().elements)) assert.match(html, new RegExp(`id="${id}"`));
});
